const config = {
    // CAP/Atom endpoint. Replace with your provider feed.
    capFeedUrl: "https://alerts.metservice.com/cap/atom",

    // Event keywords (case-insensitive) that trigger storm mode.
    // Match is by substring against CAP event title.
    watchEvents: [
        "storm",
        "severe thunderstorm",
        "tropical cyclone",
        "high wind",
        "gale"
    ],

    // Minimum CAP severity that can trigger action.
    // One of: Minor, Moderate, Severe, Extreme
    minSeverity: "Severe",

    // ESS storm targets
    stormMinSoc: 80,
    stormHub4Mode: 3, // Keep batteries charged

    // Defaults used if baseline is unknown.
    normalMinSoc: 20,
    normalHub4Mode: 1,

    // Optional fixed fallback location if GPS topics are unavailable.
    // Set to null to disable fixed fallback.
    homeLat: null,
    homeLon: null,

    // Optional override if portal id cannot be inferred from MQTT topics.
    portalId: null,

    // If true, re-send storm setpoints on every poll while active.
    enforceWhileActive: false
};

flow.set("stormConfig", config);

const state = flow.get("stormState") || { active: false };
flow.set("stormState", state);

msg.payload = {
    action: "init",
    config,
    state
};
return msg;

const cfg = flow.get("stormConfig") || {};
if (!cfg.capFeedUrl) {
    node.warn("stormConfig.capFeedUrl is missing");
    return null;
}

msg.method = "GET";
msg.url = cfg.capFeedUrl;
msg.headers = {
    "accept": "application/atom+xml, application/xml, text/xml;q=0.9, */*;q=0.8"
};
return msg;

function decodeXml(text) {
    if (typeof text !== "string") return "";
    return text
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, "\"")
        .replace(/&#39;/g, "'")
        .replace(/&apos;/g, "'")
        .replace(/&amp;/g, "&");
}

function stripTags(text) {
    return decodeXml(String(text || "").replace(/<[^>]*>/g, "")).trim();
}

function extractFirst(segment, tagNames) {
    for (const tagName of tagNames) {
        const re = new RegExp(`<(?:\\w+:)?${tagName}\\b[^>]*>([\\s\\S]*?)<\\/(?:\\w+:)?${tagName}>`, "i");
        const m = segment.match(re);
        if (m && m[1] !== undefined) {
            const v = stripTags(m[1]);
            if (v) return v;
        }
    }
    return "";
}

function extractAll(segment, tagName) {
    const re = new RegExp(`<(?:\\w+:)?${tagName}\\b[^>]*>([\\s\\S]*?)<\\/(?:\\w+:)?${tagName}>`, "gi");
    const out = [];
    let m;
    while ((m = re.exec(segment)) !== null) {
        const v = stripTags(m[1]);
        if (v) out.push(v);
    }
    return out;
}

function parseEntries(xmlText, containerTag) {
    const re = new RegExp(`<(?:\\w+:)?${containerTag}\\b[\\s\\S]*?<\\/(?:\\w+:)?${containerTag}>`, "gi");
    return xmlText.match(re) || [];
}

const xml = typeof msg.payload === "string" ? msg.payload : String(msg.payload || "");

const entryBlocks = parseEntries(xml, "entry");
const alertBlocks = entryBlocks.length ? [] : parseEntries(xml, "alert");
const blocks = entryBlocks.length ? entryBlocks : alertBlocks;

const alerts = [];
for (const b of blocks) {
    const alert = {
        id: extractFirst(b, ["id", "identifier"]),
        event: extractFirst(b, ["event"]),
        severity: extractFirst(b, ["severity"]),
        urgency: extractFirst(b, ["urgency"]),
        certainty: extractFirst(b, ["certainty"]),
        headline: extractFirst(b, ["headline", "title"]),
        effective: extractFirst(b, ["effective", "updated", "published"]),
        expires: extractFirst(b, ["expires"]),
        areaDesc: extractFirst(b, ["areaDesc"]),
        polygons: extractAll(b, "polygon"),
        circles: extractAll(b, "circle")
    };

    // Keep records that are likely useful CAP alerts.
    if (alert.event || alert.headline || alert.polygons.length || alert.circles.length) {
        alerts.push(alert);
    }
}

msg.payload = {
    fetchedAt: new Date().toISOString(),
    sourceUrl: msg.url,
    count: alerts.length,
    alerts
};

return msg;

function extractValue(payload) {
    if (payload && typeof payload === "object" && payload.value !== undefined) {
        return Number(payload.value);
    }
    return Number(payload);
}

const topic = String(msg.topic || "");
const parts = topic.split("/");
if (parts.length > 2 && parts[1]) {
    flow.set("portalId", parts[1]);
}

const v = extractValue(msg.payload);
if (!Number.isFinite(v)) return null;

if (topic.endsWith("/Latitude")) {
    flow.set("gpsLat", v);
} else if (topic.endsWith("/Longitude")) {
    flow.set("gpsLon", v);
} else {
    return null;
}

msg.payload = {
    portalId: flow.get("portalId"),
    gpsLat: flow.get("gpsLat"),
    gpsLon: flow.get("gpsLon")
};

return msg;

function extractValue(payload) {
    if (payload && typeof payload === "object" && payload.value !== undefined) {
        return Number(payload.value);
    }
    return Number(payload);
}

const topic = String(msg.topic || "");
const value = extractValue(msg.payload);
if (!Number.isFinite(value)) return null;

const parts = topic.split("/");
if (parts.length > 2 && parts[1]) {
    flow.set("portalId", parts[1]);
}

const stormState = flow.get("stormState") || { active: false };

if (topic.endsWith("/BatteryLife/MinimumSocLimit")) {
    flow.set("currentMinSoc", value);
    if (!stormState.active) {
        flow.set("baselineMinSoc", value);
    }
} else if (topic.endsWith("/Hub4Mode")) {
    flow.set("currentHub4Mode", value);
    if (!stormState.active) {
        flow.set("baselineHub4Mode", value);
    }
} else {
    return null;
}

msg.payload = {
    portalId: flow.get("portalId"),
    currentMinSoc: flow.get("currentMinSoc"),
    baselineMinSoc: flow.get("baselineMinSoc"),
    currentHub4Mode: flow.get("currentHub4Mode"),
    baselineHub4Mode: flow.get("baselineHub4Mode"),
    stormActive: stormState.active
};

return msg;

const cfg = flow.get("stormConfig") || {};
const now = Date.now();

function toNumber(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function severityRank(sev) {
    const map = {
        unknown: 0,
        minor: 1,
        moderate: 2,
        severe: 3,
        extreme: 4
    };
    return map[String(sev || "unknown").toLowerCase()] ?? 0;
}

function watchEventMatches(event) {
    const patterns = Array.isArray(cfg.watchEvents) ? cfg.watchEvents : [];
    if (!patterns.length) return true;
    const e = String(event || "").toLowerCase();
    return patterns.some(p => e.includes(String(p || "").toLowerCase()));
}

function parsePoints(polyText) {
    const points = [];
    const re = /(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/g;
    let m;
    while ((m = re.exec(String(polyText || ""))) !== null) {
        const lat = Number(m[1]);
        const lon = Number(m[2]);
        if (Number.isFinite(lat) && Number.isFinite(lon)) {
            points.push({ lat, lon });
        }
    }
    return points;
}

function pointInPolygon(lat, lon, polygon) {
    if (!Array.isArray(polygon) || polygon.length < 3) return false;
    const x = lon;
    const y = lat;
    let inside = false;

    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
        const xi = polygon[i].lon;
        const yi = polygon[i].lat;
        const xj = polygon[j].lon;
        const yj = polygon[j].lat;

        const intersect = ((yi > y) !== (yj > y)) &&
            (x < ((xj - xi) * (y - yi)) / ((yj - yi) || 1e-12) + xi);
        if (intersect) inside = !inside;
    }

    return inside;
}

function parseCircle(circleText) {
    const nums = String(circleText || "").match(/-?\d+(?:\.\d+)?/g);
    if (!nums || nums.length < 3) return null;
    const lat = Number(nums[0]);
    const lon = Number(nums[1]);
    const km = Number(nums[2]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || !Number.isFinite(km)) return null;
    return { lat, lon, km };
}

function distanceKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
        Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
}

function isInAlertZone(alert, lat, lon) {
    const polygons = Array.isArray(alert.polygons) ? alert.polygons : [];
    for (const polyText of polygons) {
        const pts = parsePoints(polyText);
        if (pointInPolygon(lat, lon, pts)) return true;
    }

    const circles = Array.isArray(alert.circles) ? alert.circles : [];
    for (const circleText of circles) {
        const c = parseCircle(circleText);
        if (!c) continue;
        if (distanceKm(lat, lon, c.lat, c.lon) <= c.km) return true;
    }

    return false;
}

const portalId = flow.get("portalId") || cfg.portalId || null;
const gpsLat = toNumber(flow.get("gpsLat"));
const gpsLon = toNumber(flow.get("gpsLon"));
const homeLat = gpsLat ?? toNumber(cfg.homeLat);
const homeLon = gpsLon ?? toNumber(cfg.homeLon);

const stormState = flow.get("stormState") || { active: false };
const minSeverity = severityRank(cfg.minSeverity || "Severe");
const alerts = (msg.payload && Array.isArray(msg.payload.alerts)) ? msg.payload.alerts : [];

let matched = [];
if (homeLat !== null && homeLon !== null) {
    matched = alerts.filter(a => {
        const sev = severityRank(a.severity);
        if (sev < minSeverity) return false;
        if (!watchEventMatches(a.event || a.headline)) return false;

        if (a.expires) {
            const expiresTs = Date.parse(a.expires);
            if (Number.isFinite(expiresTs) && expiresTs < now) return false;
        }

        return isInAlertZone(a, homeLat, homeLon);
    });
}

const shouldStorm = matched.length > 0;

const baselineMinSoc = toNumber(flow.get("baselineMinSoc")) ?? toNumber(cfg.normalMinSoc) ?? 20;
const baselineHub4Mode = toNumber(flow.get("baselineHub4Mode")) ?? toNumber(cfg.normalHub4Mode) ?? 1;
const stormMinSoc = toNumber(cfg.stormMinSoc) ?? 80;
const stormHub4Mode = toNumber(cfg.stormHub4Mode) ?? 3;

function writeMsg(path, value, reason) {
    return {
        topic: `W/${portalId}${path}`,
        payload: { value },
        reason,
        retain: false,
        qos: 0
    };
}

const status = {
    timestamp: new Date().toISOString(),
    portalId,
    homeLat,
    homeLon,
    alertCount: alerts.length,
    matchedCount: matched.length,
    matchedAlerts: matched.map(a => ({
        event: a.event,
        severity: a.severity,
        expires: a.expires,
        headline: a.headline
    })),
    previousState: stormState.active ? "storm" : "normal",
    nextState: shouldStorm ? "storm" : "normal"
};

if (homeLat === null || homeLon === null) {
    status.note = "No location available (GPS or fixed homeLat/homeLon).";
    flow.set("stormState", stormState);
    return [null, status];
}

if (!portalId) {
    status.note = "No portalId found. Ensure MQTT topics are arriving or set stormConfig.portalId.";
    flow.set("stormState", stormState);
    return [null, status];
}

let commandMsgs = null;

if (shouldStorm && (!stormState.active || cfg.enforceWhileActive)) {
    stormState.active = true;
    stormState.lastChange = status.timestamp;
    stormState.lastReason = "storm_enter";
    commandMsgs = [
        writeMsg("/settings/0/Settings/CGwacs/BatteryLife/MinimumSocLimit", stormMinSoc, "storm_enter_min_soc"),
        writeMsg("/settings/0/Settings/CGwacs/Hub4Mode", stormHub4Mode, "storm_enter_hub4_mode")
    ];
    status.transition = "storm_enter";
} else if (!shouldStorm && stormState.active) {
    stormState.active = false;
    stormState.lastChange = status.timestamp;
    stormState.lastReason = "storm_exit";
    commandMsgs = [
        writeMsg("/settings/0/Settings/CGwacs/BatteryLife/MinimumSocLimit", baselineMinSoc, "storm_exit_restore_min_soc"),
        writeMsg("/settings/0/Settings/CGwacs/Hub4Mode", baselineHub4Mode, "storm_exit_restore_hub4_mode")
    ];
    status.transition = "storm_exit";
} else {
    status.transition = "no_change";
}

flow.set("stormState", stormState);

return [commandMsgs, status];
